def merge_patch(target, patch):
    """
    Apply JSON merge-patch semantics to target using patch.

    - If patch is not a dict, return a copy of patch.
    - If patch is a dict:
        - If target is not a dict, treat it as {}.
        - For each key in patch:
            - If value is None, delete the key from result.
            - Otherwise, recursively merge.
        - Keys in target not in patch are preserved (copied).
    - Never mutate or alias mutable input containers.
    """
    # Helper to deep copy JSON types without imports
    def _copy(value):
        if isinstance(value, dict):
            return {k: _copy(v) for k, v in value.items()}
        elif isinstance(value, list):
            return [_copy(v) for v in value]
        else:
            # JSON scalars: str, int, float, bool, None
            return value

    # If patch is not a dict, it replaces target entirely
    if not isinstance(patch, dict):
        return _copy(patch)

    # If target is not a dict, treat as empty dict
    if not isinstance(target, dict):
        target = {}

    result = {}

    # Start with a copy of target
    for key, value in target.items():
        result[key] = _copy(value)

    # Apply patch
    for key, value in patch.items():
        if value is None:
            # Delete key if present
            if key in result:
                del result[key]
        else:
            # Recursively merge
            if key in result:
                result[key] = merge_patch(result[key], value)
            else:
                result[key] = _copy(value)

    return result
